import streamlit as st

st.title("🥠행운을 부르는 포춘쿠키")
st.success("현서가 준비한 특별한 포춘쿠키")
st.subheader("포춘쿠키를 열어보기")
open_cookies = st.button("포춘쿠키 확인하기")
st.subheader("포춘쿠키 열어보기")
import pandas as pd
messages = pd.read_csv("./message/fighting.csv")
import random
import time
if open_cookies:
    placeholder = st.empty()
    with placeholder.container():
        st.image("data:image/jpeg;base64,", width=250)
        st.write("포춘쿠키를 여는 중 입니다...")
    time.sleep(3)
    placeholder.empty()
    fortune = random.choice(messages.message)
    st.warning(fortune)